#include <iostream>
#include <vector>

class IntBuffer {
public:
    // Explicit constructor prevents implicit int -> IntBuffer conversion
    explicit IntBuffer(size_t size) : data_(size, 0) {}

    // Explicit conversion operator to bool (C++11/C++17)
    explicit operator bool() const {
        return !data_.empty();
    }

    size_t size() const { return data_.size(); }

private:
    std::vector<int> data_;
};

void inspectBuffer(const IntBuffer& buf) {
    std::cout << "Buffer valid: " << (buf ? "true" : "false")
              << ", Size: " << buf.size() << "\n";
}

int main() {
    // inspectBuffer(5); // COMPILE ERROR: cannot convert 'int' to 'const IntBuffer&'
    inspectBuffer(IntBuffer(5)); // OK: Explicit constructor call

    IntBuffer emptyBuf(0);
    // bool b = emptyBuf; // COMPILE ERROR: cannot convert explicitly to bool
    bool b = static_cast<bool>(emptyBuf); // OK: Explicit cast
    std::cout << "Cast empty buffer: " << (b ? "true" : "false") << "\n";

    return 0;
}

#include <iostream>
#include <vector>

class Matrix2D {
public:
    Matrix2D(size_t rows, size_t cols) 
        : rows_(rows), cols_(cols), data_(rows * cols, 0) {}

    // Overloading operator() for 2D indexing (non-const)
    int& operator()(size_t r, size_t c) {
        return data_[r * cols_ + c];
    }

    // Overloading operator() for 2D indexing (const)
    const int& operator()(size_t r, size_t c) const {
        return data_[r * cols_ + c];
    }

    size_t rows() const { return rows_; }
    size_t cols() const { return cols_; }

private:
    size_t rows_;
    size_t cols_;
    std::vector<int> data_;
};

int main() {
    Matrix2D mat(2, 2);
    mat(0, 0) = 10;
    mat(0, 1) = 20;
    mat(1, 0) = 30;
    mat(1, 1) = 40;

    for (size_t r = 0; r < mat.rows(); ++r) {
        for (size_t c = 0; c < mat.cols(); ++c) {
            std::cout << mat(r, c) << " ";
        }
        std::cout << "\n";
    }
    return 0;
}
